<?php
require_once __DIR__.'/../../includes/db.php';require_once __DIR__.'/../includes/auth.php';require_once __DIR__.'/../includes/business_helpers.php';require_login();
if(!is_admin()){http_response_code(403);exit('Admin access required.');}
$id=(int)($_GET['id']??0);$st=$conn->prepare("SELECT dc.*,d.name dalali_name,d.phone dalali_phone,c.car_name,c.plate_number,c.chassis_number,cs.sale_date FROM dalali_commissions dc JOIN dalalis d ON d.id=dc.dalali_id JOIN cars c ON c.id=dc.car_id JOIN car_sales cs ON cs.id=dc.sale_id WHERE dc.id=?");$st->bind_param('i',$id);$st->execute();$r=$st->get_result()->fetch_assoc();if(!$r){set_flash('error','Commission not found.');redirect_to('backend/dalali/index.php');}
if($r['status']==='PAID'){redirect_to('backend/dalali/commission_receipt.php?id='.$id);}if($r['status']==='CANCELLED'){set_flash('error','Cancelled commission cannot be paid.');redirect_to('backend/dalali/view.php?id='.$r['dalali_id']);}
$error='';if($_SERVER['REQUEST_METHOD']==='POST'){$date=$_POST['paid_date']??'';$method=trim($_POST['payment_method']??'');$ref=trim($_POST['payment_reference']??'');$notes=trim($_POST['payment_notes']??'');$uid=(int)$_SESSION['user_id'];if($date===''||$method===''){$error='Payment date and method are required.';}else{$before=$r;$st=$conn->prepare("UPDATE dalali_commissions SET status='PAID',paid_date=?,payment_method=?,payment_reference=?,paid_by=?,notes=CONCAT(COALESCE(notes,''),CASE WHEN COALESCE(notes,'')='' THEN '' ELSE '\n' END,?) WHERE id=? AND status='PENDING'");$st->bind_param('sssisi',$date,$method,$ref,$uid,$notes,$id);if($st->execute()&&$st->affected_rows){car_sales_audit($conn,'PAYMENT','dalali_commission',$id,'Paid dalali commission of '.money($r['amount']).' to '.$r['dalali_name'].'.',$before,['paid_date'=>$date,'payment_method'=>$method,'payment_reference'=>$ref,'paid_by'=>$uid]);set_flash('success','Dalali commission payment recorded.');redirect_to('backend/dalali/commission_receipt.php?id='.$id);}else{$error='Could not record commission payment.';}}}
$page_title='Pay Dalali Commission';include __DIR__.'/../includes/header.php';include __DIR__.'/../includes/leftsidebar.php';?>
<div class="content-page"><h1 class="page-title">Pay Dalali Commission</h1><div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(280px,1fr))"><div class="card"><h2>Commission</h2><p><strong>Dalali:</strong> <?=e($r['dalali_name'])?> (<?=e($r['dalali_phone'])?>)</p><p><strong>Vehicle:</strong> <?=e($r['car_name'].' / '.car_sales_plate_label($r['plate_number']))?></p><p><strong>Sale Date:</strong> <?=e($r['sale_date'])?></p><p><strong>Amount Due:</strong> <?=money($r['amount'])?></p></div><div class="card form-card"><?php if($error):?><div class="flash-message error" style="position:static"><?=e($error)?></div><?php endif;?><form method="post"><div class="form-group"><label>Payment Date *</label><input type="date" name="paid_date" value="<?=date('Y-m-d')?>" required></div><div class="form-group"><label>Payment Method *</label><select name="payment_method" required><option value="Cash">Cash</option><option value="M-Pesa">M-Pesa</option><option value="Airtel Money">Airtel Money</option><option value="Mixx by Yas / Tigo Pesa">Mixx by Yas / Tigo Pesa</option><option value="Bank Transfer">Bank Transfer</option><option value="Cheque">Cheque</option><option value="Other">Other</option></select></div><div class="form-group"><label>Payment Reference</label><input name="payment_reference" placeholder="Transaction / receipt / bank reference"></div><div class="form-group"><label>Payment Notes</label><textarea name="payment_notes" rows="3"></textarea></div><button class="btn btn-green">Confirm Payment</button> <a class="btn btn-dark" href="view.php?id=<?=$r['dalali_id']?>">Cancel</a></form></div></div></div>
<?php include __DIR__.'/../includes/footer.php';?>
